'@ | ConvertFrom-Json

$all = @($existing) + @($newJson)
$hintByTopic = @{
  'món ăn vùng miền' = 'Để ý nguyên liệu hoặc cách phục vụ được mô tả.'
  'địa danh & địa lý' = 'Dựa vào vị trí và đặc điểm cảnh quan được nêu.'
  'phong tục & lễ hội' = 'Tìm nét thực hành văn hóa hoặc dịp hội được nhắc tới.'
  'phương ngữ & cách gọi' = 'Đối chiếu cách nói địa phương với tiếng phổ thông.'
  'đời sống thường ngày' = 'Nghĩ về vật dụng hay sinh hoạt quen thuộc của địa phương.'
}
$rng = [System.Random]::new(20261030)
foreach ($q in $all) {
  $q | Add-Member -NotePropertyName goiY -NotePropertyValue $hintByTopic[$q.chuDe] -Force
  $indices = [System.Collections.Generic.List[int]]@(0,1,2,3)
  for ($i = $indices.Count - 1; $i -gt 0; $i--) { $j = $rng.Next($i + 1); $tmp = $indices[$i]; $indices[$i] = $indices[$j]; $indices[$j] = $tmp }
  $oldOptions = @($q.luaChon)
  $newOptions = foreach ($index in $indices) { $oldOptions[$index] }
  $q.dapAn = [array]::IndexOf($indices.ToArray(), [int]$q.dapAn)
  $q.luaChon = @($newOptions)
}
$all | ConvertTo-Json -Depth 5 | Set-Content -Encoding utf8 $path
